SELECT 
FROM publications p JOIN categories cat ON cat.id = p.category_id
WHERE cat.is_deleted = false AND  AND p.id = #{id}

SELECT body.preview_markdown,  body.version, body.updated_at
FROM publication_contents body JOIN publications p ON p.id = body.publication_id
WHERE body.is_deleted = false AND  AND p.id = #{id}
